const STORE_EMAIL = "easagerduckins@gmail.com";

// EmailJS thank-you email (sent to the customer after a successful order).
// Fill these 3 values from your EmailJS dashboard (see EMAILJS-SETUP.txt).
const EMAILJS_PUBLIC_KEY = "sCkQVBehex7btgpO2";
const EMAILJS_SERVICE_ID = "easagerduckins@gmail.com";
const EMAILJS_TEMPLATE_ID = "template_syt9s9b";

function sendThankYouEmail({ email, name, items, total }) {
  if (!window.emailjs || EMAILJS_PUBLIC_KEY.startsWith("YOUR_")) return;
  const itemsHtml = items.map(item => `${item.name} (${item.size}, ${item.color})`).join("<br>");
  emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
    to_email: email,
    customer_name: name,
    ordered_from: "Eaesgr Duckins",
    total_cost: total,
    items: itemsHtml
  }, { publicKey: EMAILJS_PUBLIC_KEY }).catch(error => console.error("Thank-you email error:", error));
}

